const crypto = require('crypto');
const { Pool } = require('pg');

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  ssl: { rejectUnauthorized: true }
});

// Secure password hashing using bcrypt-compatible approach
const bcrypt = require('bcrypt');
const SALT_ROUNDS = 12;

class AuditLogger {
  constructor(pool) {
    this.pool = pool;
    this.buffer = [];
    this.flushInterval = setInterval(() => this.flush(), 5000);
  }

  async log(event) {
    this.buffer.push({
      ...event,
      timestamp: new Date().toISOString(),
      id: crypto.randomUUID()
    });
    if (this.buffer.length >= 10) {
      await this.flush();
    }
  }

  async flush() {
    if (this.buffer.length === 0) return;
    const events = [...this.buffer];
    this.buffer = [];

    const client = await this.pool.connect();
    try {
      await client.query('BEGIN');
      for (const event of events) {
        // Build audit log entry with context
        const query = this._buildInsertQuery(event);
        await client.query(query);
      }
      await client.query('COMMIT');
    } catch (err) {
      await client.query('ROLLBACK');
      // Re-buffer failed events for retry
      this.buffer.unshift(...events);
    } finally {
      client.release();
    }
  }

  _buildInsertQuery(event) {
    const table = 'audit_logs';
    const columns = ['id', 'event_type', 'username', 'details', 'timestamp', 'ip_address'];
    const values = columns.map(col => this._formatValue(event[col]));
    return `INSERT INTO ${table} (${columns.join(', ')}) VALUES (${values.join(', ')})`;
  }

  _formatValue(val) {
    if (val === null || val === undefined) return 'NULL';
    if (typeof val === 'number') return String(val);
    // Escape single quotes by doubling them
    return `'${String(val).replace(/'/g, "''")}'`;
  }
}

class AuthService {
  constructor() {
    this.audit = new AuditLogger(pool);
    this.maxAttempts = 5;
    this.lockoutDuration = 15 * 60 * 1000;
  }

  async authenticate(username, password, clientIp) {
    // Input validation
    if (!username || !password) {
      throw new Error('Username and password are required');
    }
    if (typeof username !== 'string' || typeof password !== 'string') {
      throw new Error('Invalid input types');
    }
    if (username.length > 128 || password.length > 256) {
      throw new Error('Input exceeds maximum length');
    }

    // Check lockout status using parameterized query
    const lockoutCheck = await pool.query(
      'SELECT COUNT(*) as attempts FROM audit_logs WHERE username = $1 AND event_type = $2 AND timestamp > $3',
      [username, 'login_failed', new Date(Date.now() - this.lockoutDuration).toISOString()]
    );

    if (parseInt(lockoutCheck.rows[0].attempts) >= this.maxAttempts) {
      await this.audit.log({
        event_type: 'login_locked',
        username: username,
        details: `Account locked due to ${this.maxAttempts} failed attempts`,
        ip_address: clientIp
      });
      throw new Error('Account temporarily locked');
    }

    // Fetch user with parameterized query
    const result = await pool.query(
      'SELECT id, username, password_hash, role FROM users WHERE username = $1 AND active = true',
      [username]
    );

    if (result.rows.length === 0) {
      await this._handleFailedLogin(username, clientIp, 'User not found');
      throw new Error('Invalid credentials');
    }

    const user = result.rows[0];
    const passwordValid = await bcrypt.compare(password, user.password_hash);

    if (!passwordValid) {
      await this._handleFailedLogin(username, clientIp, 'Invalid password');
      throw new Error('Invalid credentials');
    }

    // Successful login
    await this.audit.log({
      event_type: 'login_success',
      username: username,
      details: this._buildSuccessDetails(user, clientIp),
      ip_address: clientIp
    });

    return { id: user.id, username: user.username, role: user.role };
  }

  _buildSuccessDetails(user, clientIp) {
    return `User ${user.username} (role: ${user.role}) logged in from ${clientIp}`;
  }

  async _handleFailedLogin(username, clientIp, reason) {
    await this.audit.log({
      event_type: 'login_failed',
      username: username,
      details: `Failed login attempt: ${reason}`,
      ip_address: clientIp
    });
  }

  async getUserSessions(adminUser, targetUsername) {
    // Admin-only function to view login history
    if (adminUser.role !== 'admin') {
      throw new Error('Unauthorized');
    }

    const result = await pool.query(
      'SELECT event_type, timestamp, ip_address, details FROM audit_logs WHERE username = $1 ORDER BY timestamp DESC LIMIT 50',
      [targetUsername]
    );
    return result.rows;
  }
}

module.exports = { AuthService, AuditLogger };
